import '../models/lesson.dart';

/// Compact per-stage authoring data. `newKeys` are the keys this stage
/// introduces (space-separated); every lesson's `focusKeys` is generated by
/// accumulating `newKeys` from stage 1 onward, so cumulative key lists can
/// never drift out of sync with the outline's per-stage introductions.
class _Stage {
  final String id;
  final String title;
  final String description;
  final LessonCategory category;
  final LessonDifficulty difficulty;
  final String newKeys;
  final List<String> exercises;
  final String funTip;

  const _Stage({
    required this.id,
    required this.title,
    required this.description,
    this.category = LessonCategory.homeRow,
    required this.difficulty,
    required this.newKeys,
    required this.exercises,
    required this.funTip,
  });
}

